import{_ as n,c as t,o as r,a2 as i}from"./chunks/framework.CIiVzG-O.js";const d=JSON.parse('{"title":"Einführung","description":"","frontmatter":{},"headers":[],"relativePath":"de/guide/introduction.md","filePath":"de/guide/introduction.md","lastUpdated":1793163976000}'),a={name:"de/guide/introduction.md"};function s(l,e,o,u,h,g){return r(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="einfuhrung" tabindex="-1">Einführung <a class="header-anchor" href="#einfuhrung" aria-label="Permalink to &quot;Einführung&quot;">​</a></h1><h2 id="uber-nuezip" tabindex="-1">Über NueZip <a class="header-anchor" href="#uber-nuezip" aria-label="Permalink to &quot;Über NueZip&quot;">​</a></h2><p>NueZip ist ein professioneller Archivmanager für macOS, der auf Geschwindigkeit, Zuverlässigkeit und einfache Bedienung ausgelegt ist. Ob Sie Dateien komprimieren, Archive entpacken, Formate konvertieren oder kennwortgeschützte Archive verwalten müssen — NueZip erledigt alles mit einem nativen macOS-Erlebnis.</p><p>NueZip ist mit Swift 6 und SwiftUI entwickelt und nutzt Apple Silicon und macOS-Technologien voll aus, um ein schnelles, schlankes und sicheres Werkzeug zur Archivverwaltung bereitzustellen.</p><h2 id="hauptfunktionen" tabindex="-1">Hauptfunktionen <a class="header-anchor" href="#hauptfunktionen" aria-label="Permalink to &quot;Hauptfunktionen&quot;">​</a></h2><h3 id="📦-multi-format-unterstutzung" tabindex="-1">📦 <strong>Multi-Format-Unterstützung</strong> <a class="header-anchor" href="#📦-multi-format-unterstutzung" aria-label="Permalink to &quot;📦 **Multi-Format-Unterstützung**&quot;">​</a></h3><p>NueZip unterstützt alle gängigen Archivformate:</p><ul><li><strong>RAR</strong> — Nur-Lesen mit Multi-Volume-Unterstützung</li><li><strong>ZIP</strong> — Universelle Komprimierung mit AES-Verschlüsselung</li><li><strong>7-Zip</strong> — Hohes Kompressionsverhältnis mit LZMA2</li><li><strong>TAR</strong> — Archivbündelung mit optionalem GZIP/BZIP2</li><li><strong>GZIP / BZIP2</strong> — Eigenständige Kompressionsformate</li></ul><h3 id="⚡-schnelles-entpacken" tabindex="-1">⚡ <strong>Schnelles Entpacken</strong> <a class="header-anchor" href="#⚡-schnelles-entpacken" aria-label="Permalink to &quot;⚡ **Schnelles Entpacken**&quot;">​</a></h3><p>Die Zwei-Engine-Architektur wählt das optimale Backend für jedes Format aus und sorgt so für die schnellstmöglichen Extraktionsgeschwindigkeiten.</p><h3 id="🔐-passwortschutz-verschlusselung" tabindex="-1">🔐 <strong>Passwortschutz &amp; Verschlüsselung</strong> <a class="header-anchor" href="#🔐-passwortschutz-verschlusselung" aria-label="Permalink to &quot;🔐 **Passwortschutz &amp; Verschlüsselung**&quot;">​</a></h3><p>Erstellen Sie passwortgeschützte Archive mit branchenüblicher Verschlüsselung. Der integrierte Passwort-Manager speichert Anmeldedaten sicher in Ihrem lokalen Schlüsselbund.</p><h3 id="📋-stapelverarbeitung" tabindex="-1">📋 <strong>Stapelverarbeitung</strong> <a class="header-anchor" href="#📋-stapelverarbeitung" aria-label="Permalink to &quot;📋 **Stapelverarbeitung**&quot;">​</a></h3><p>Verarbeiten Sie mehrere Dateien auf einmal:</p><ul><li><strong>Stapelkomprimierung</strong> — Komprimieren Sie mehrere Elemente in einzelne Archive</li><li><strong>Stapelextraktion</strong> — Entpacken Sie mehrere Archive gleichzeitig</li><li><strong>Stapelkonvertierung</strong> — Konvertieren Sie Archive in großen Mengen zwischen Formaten</li><li><strong>Stapelverschlüsselung</strong> — Wenden Sie Passwortschutz auf mehrere Archive an</li></ul><h3 id="🛠️-erweiterte-werkzeuge" tabindex="-1">🛠️ <strong>Erweiterte Werkzeuge</strong> <a class="header-anchor" href="#🛠️-erweiterte-werkzeuge" aria-label="Permalink to &quot;🛠️ **Erweiterte Werkzeuge**&quot;">​</a></h3><ul><li><strong>Archiv-Reparatur</strong> — Reparieren Sie beschädigte RAR- und ZIP-Archive</li><li><strong>Formatkonvertierung</strong> — Konvertieren Sie zwischen allen unterstützten Formaten</li><li><strong>Leistungs-Benchmark</strong> — Testen Sie Kompressionsgeschwindigkeit und Bewertung</li><li><strong>Archivsuche</strong> — Finden Sie Dateien innerhalb von Archiven nach Namen</li><li><strong>Datei-Info-Betrachter</strong> — Zeigen Sie detaillierte Metadaten für Archiveinträge an</li><li><strong>Volume/Split-Unterstützung</strong> — Erstellen Sie Multi-Volume-Archive</li></ul><h3 id="🖥️-natives-macos-erlebnis" tabindex="-1">🖥️ <strong>Natives macOS-Erlebnis</strong> <a class="header-anchor" href="#🖥️-natives-macos-erlebnis" aria-label="Permalink to &quot;🖥️ **Natives macOS-Erlebnis**&quot;">​</a></h3><ul><li><strong>Swift 6 + SwiftUI</strong> — Modernes, responsives Interface</li><li><strong>Apple Silicon nativ</strong> — Optimiert für M-Serie-Chips</li><li><strong>Finder-Integration</strong> — Kontextmenü-Erweiterung per Rechtsklick</li><li><strong>Drag &amp; Drop</strong> — Schneller Zugriff über das Menüleisten-Drop-Panel</li><li><strong>Minimale Ressourcennutzung</strong> — Schlanke Hintergrundausführung</li></ul><h2 id="systemanforderungen" tabindex="-1">Systemanforderungen <a class="header-anchor" href="#systemanforderungen" aria-label="Permalink to &quot;Systemanforderungen&quot;">​</a></h2><ul><li><strong>Betriebssystem</strong>: macOS 14 Sonoma oder neuer</li><li><strong>CPU</strong>: Apple Silicon (M-Serie) oder Intel (64-Bit)</li><li><strong>Arbeitsspeicher</strong>: 4 GB RAM mindestens, 8 GB empfohlen</li><li><strong>Speicher</strong>: ~50 MB für die Installation</li></ul><h2 id="unterstutzte-sprachen" tabindex="-1">Unterstützte Sprachen <a class="header-anchor" href="#unterstutzte-sprachen" aria-label="Permalink to &quot;Unterstützte Sprachen&quot;">​</a></h2><p>NueZip unterstützt Englisch, Chinesisch (Vereinfacht), Chinesisch (Traditionell), Japanisch, Koreanisch und viele weitere Sprachen.</p><h2 id="erste-schritte" tabindex="-1">Erste Schritte <a class="header-anchor" href="#erste-schritte" aria-label="Permalink to &quot;Erste Schritte&quot;">​</a></h2><p>Wenn Sie neu bei NueZip sind, beginnen Sie mit der <a href="/de/guide/installation.html">Installationsanleitung</a>, um die Anwendung auf Ihrem Mac zum Laufen zu bringen.</p>',25)])])}const m=n(a,[["render",s]]);export{d as __pageData,m as default};
